            aux + 1,
            target_block * 16 + 12,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathRight { level: level as u8 },
            aux + 1,
            target_block * 16,
        ));
    }

    for (value, source_row, destination_row) in
        [(0u8, 44usize, 960usize), (1, 460, 962), (2, 508, 964)]
    {
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::ValueSource { value },
            source_row,
